/* PARTIE 2 — Traumatismes, immobilisations, extraction, secours routier (MAJ 05/2024) */
var S21 = 'Séquence 2.1 — Les traumatismes et immobilisations', S22 = 'Séquence 2.2 — Extraction d’une victime assise', S23 = 'Séquence 2.3 — Secours routiers';

VSAV.chap({
  id: 'trauma-membres', part: 'p2', seq: S21, title: 'Traumatisme des membres : écharpe, attelle à dépression, réalignement', short: 'Trauma des membres', motif: 'bone', accent: '#b45309',
  sources: ['PR - Traumatisme des membres (MAJ 05/2024)', 'FT - Mise en place d’une écharpe', 'FT - Immobilisation d’un membre au moyen d’une attelle à dépression', 'FT - Réalignement de membre'],
  summary: 'Limiter les mouvements, immobiliser lésion + articulations voisines, gérer fracture ouverte et déformation.',
  why: '<b>Pourquoi bloquer les articulations au-dessus et au-dessous ?</b> Une attelle qui ne prend que le foyer de fracture laisse bouger les deux fragments par l’intermédiaire des articulations : la douleur persiste et les complications (vaisseaux, nerfs) restent possibles. Le froid limite le gonflement et la douleur — sauf sur une fracture ouverte (plaie).',
  sections: [
    { id: 'cat', t: 'Conduite à tenir (PR)', ic: 'list', src: 'PR - Traumatisme des membres',
      steps: ['Limiter autant que possible les mouvements du membre blessé.', 'Membre inférieur : victime allongée, consigne de ne pas bouger. Membre supérieur : victime assise, membre contre la poitrine, soutenu par l’autre main dans la position la moins douloureuse.', 'Immobiliser avec l’attelle la plus appropriée : toujours la lésion ET les articulations au-dessus et en dessous.', 'Appliquer du froid si possible, sauf fracture ouverte.', 'Poursuivre le bilan et surveiller.'],
      after: '<div class="tw"><table><tr><th>Fracture…</th><th>Conduite</th></tr><tr><td>Ouverte, non hémorragique</td><td>Pansement stérile sur la plaie avant l’immobilisation</td></tr><tr><td>Ouverte avec saignement abondant</td><td>Conduite hémorragie externe avant toute immobilisation ; massif → garrot</td></tr><tr><td>Avec os ou corps étranger visible</td><td>Ne toucher ni à l’os ni au corps étranger (ils peuvent limiter le saignement)</td></tr><tr><td>Avec déformation</td><td>Immobiliser en respectant la déformation ; le réalignement est réalisé par un médecin ou à sa demande</td></tr></table></div><p>Perte de connaissance → conduite traumatisé inconscient qui respire. Détresse vitale consciente → conduite détresse circulatoire.</p>' },
    { id: 'echarpe', t: 'Écharpes (membre supérieur)', ic: 'hand', src: 'FT - Mise en place d’une écharpe',
      html: '<p>Quand une victime doit être mobilisée et qu’aucun moyen plus approprié (attelle modulable ou à dépression) n’est disponible. Triangle de tissu non extensible, base d’au moins <b>1,2 m</b> ; pointe opposée à la base = « sommet », les deux autres = « chefs ».</p>',
      figs: [{ svg: 'echarpe', cap: 'Quelle écharpe pour quelle lésion ?', txt: '<p>Main / poignet / avant-bras : écharpe simple, nœud sur le côté du cou. Bras : écharpe simple + contre-écharpe nouée en avant de l’aisselle opposée. Épaule : écharpe oblique nouée sur l’épaule opposée, sommet fixé sur le coude.</p>', src: 'FT - Mise en place d’une écharpe' }],
      steps: ['Écharpe simple : engager une pointe entre le coude et le thorax et la passer sur l’épaule du côté blessé (sommet côté coude, base perpendiculaire à l’avant-bras).', 'Ajuster et déplisser jusqu’à la base des doigts.', 'Rabattre la seconde pointe sur l’avant-bras et la passer sur l’épaule opposée ; nouer sur le côté du cou. Main légèrement au-dessus du coude.'], stepsTitle: 'Écharpe simple' },
    { id: 'attelle', t: 'Attelle à dépression', ic: 'bone', src: 'FT - Immobilisation d’un membre au moyen d’une attelle à dépression',
      html: '<p>Pour coude, avant-bras, poignet ; genou, jambe, cheville ; épaule avec coude éloigné du corps (attelle membre inférieur ou MID enfant pliée en « N »). Enveloppe à billes + vanne + sangles ; utilisée avec une pompe.</p>',
      steps: ['S1 et 2 : maintenir le membre (après réalignement si nécessaire) au niveau des articulations sus- et sous-jacentes.', 'S3 : préparer l’attelle (billes réparties, valve ouverte).', 'S1 et 2 : soulever de quelques centimètres en exerçant une traction douce à l’extrémité.', 'S3 : glisser l’attelle en englobant les articulations sus- et sous-jacentes.', 'S1 et 2 : déposer le membre et le maintenir. S3 : former une gouttière.', 'S1 et 2 : maintenir l’attelle contre le membre. S3 : faire le vide jusqu’à rigidité, fermer la valve, déconnecter.', 'S3 : vérifier l’immobilisation et l’état de l’extrémité du membre.'], stepsTitle: 'Membre inférieur (3 secouristes minimum)',
      after: '<p>Membre supérieur : même principe, 2 secouristes minimum. <b>Efficacité :</b> segment et articulations immobilisés, attelle fixée, douleur diminuée, pas de signe de compression (circulation en aval correcte).</p>' },
    { id: 'realignement', t: 'Réalignement de membre', ic: 'alert', src: 'FT - Réalignement de membre',
      html: '<p>Effectué chaque fois que possible par un médecin ; à défaut, <b>sur avis médical</b>, pour un avant-bras ou une jambe avec <b>fracture fermée</b> : signes de complication vasculaire ou neurologique (membre froid, pâle, insensible) ou déformation empêchant l’immobilisation.</p><ul class="check"><li><b>Avant-bras :</b> bloquer le coude d’une main, saisir poignet ou main de l’autre, ramener dans l’axe par traction douce.</li><li><b>Jambe :</b> une aide bloque le genou à deux mains ; saisir la cheville à deux mains, ramener dans l’axe par traction douce.</li><li>La traction n’est relâchée qu’<b>après immobilisation</b>.</li></ul><div class="callout bad"><b>Arrêter immédiatement</b>et redemander un avis si résistance ou douleur intolérable ; nouvel avis si complication vasculaire ou neurologique.</div>' }
  ],
  key: ['Immobiliser la lésion + articulations sus- et sous-jacentes.', 'Froid sauf fracture ouverte.', 'Fracture ouverte qui saigne : hémorragie d’abord ; os / corps étranger : ne pas y toucher.', 'Déformation : respecter ; réalignement par médecin ou sur avis (fracture fermée avant-bras / jambe).', 'Écharpe : base ≥ 1,2 m ; épaule déformée : rembourrage, ne jamais rapprocher le coude.', 'Vérifier l’extrémité après toute immobilisation.'],
  traps: ['Réaligner une fracture ouverte.', 'Relâcher la traction avant la fin de l’immobilisation.', 'Mettre de la glace sur une fracture ouverte.'],
  quiz: [
    { q: 'Lors de la pose d’une attelle, on immobilise :', c: ['La lésion et les articulations au-dessus et en dessous', 'Uniquement le foyer de fracture', 'Uniquement l’articulation au-dessus', 'Tout le corps systématiquement'], e: 'PR Traumatisme des membres.', s: 'cat' },
    { q: 'Application de froid : contre-indication ?', c: ['La fracture ouverte', 'La fracture fermée', 'L’entorse', 'La contusion'], e: 'Appliquer du froid si possible, sauf fracture ouverte.', s: 'cat' },
    { q: 'Qui peut réaligner un membre ?', c: ['Un médecin, ou le secouriste sur avis médical (fracture fermée avant-bras / jambe)', 'Tout secouriste dès qu’il voit une déformation', 'Personne', 'La victime elle-même'], e: 'FT Réalignement de membre.', s: 'realignement' },
    { q: 'Longueur minimale de la base d’une écharpe triangulaire :', c: ['1,2 m', '50 cm', '2 m', '80 cm'], e: 'FT Écharpe : 1,2 m au minimum.', s: 'echarpe' },
    { q: 'Traumatisme de l’épaule avec bras écarté du corps :', c: ['Rembourrage entre bras et tronc, ne jamais rapprocher le coude', 'Ramener le coude contre le corps', 'Écharpe simple serrée', 'Réalignement immédiat'], e: 'Respecter la déformation.', s: 'echarpe' },
    { q: 'Nombre minimal de secouristes pour une attelle à dépression au membre inférieur :', c: ['3', '1', '2', '5'], e: 'Membre inférieur : 3 ; membre supérieur : 2.', s: 'attelle' }
  ]
});

VSAV.chap({
  id: 'trauma-abdomen', part: 'p2', seq: S21, title: 'Traumatisme de l’abdomen', short: 'Trauma de l’abdomen', motif: 'shield', accent: '#c2410c',
  sources: ['PR - Traumatisme de l’abdomen (MAJ 05/2024)'],
  summary: 'À plat dos jambes fléchies, ne jamais retirer un corps étranger, protéger une éviscération.',
  why: '<b>Pourquoi jambes fléchies ?</b> Cette position relâche la paroi abdominale et soulage la victime. <b>Pourquoi laisser le corps étranger ?</b> Il peut comprimer un vaisseau : le retirer peut déclencher une hémorragie interne massive. Le risque d’<b>aggravation brutale</b> impose une surveillance attentive.',
  sections: [
    { id: 'cat', t: 'Conduite à tenir', ic: 'list', src: 'PR - Traumatisme de l’abdomen',
      html: '<div class="callout bad"><b>Interdit</b>Ne jamais retirer un corps étranger pénétrant dans l’abdomen.</div>',
      steps: ['Mettre immédiatement la victime à plat dos, jambes fléchies.', 'Rechercher des lésions dans le dos, notamment lors de la mobilisation.', 'Protéger au plus vite contre le froid, le vent ou la chaleur.', 'Poursuivre le bilan et surveiller attentivement (risque d’aggravation brutale).', 'Éviscération : ne pas remettre les viscères en place ; les envelopper dans un champ stérile humidifié au sérum physiologique, sans les mobiliser ni les comprimer (pas de compresses).', 'Détresse vitale : conduite adaptée.'],
      after: '<div class="callout warn"><b>Femme enceinte</b>Tout traumatisme violent (AVP, chute, coup dans l’abdomen) = traumatisme de l’abdomen, avec consultation dans un service d’urgence ou spécialisé.</div>' }
  ],
  key: ['Plat dos, jambes fléchies.', 'Jamais retirer un corps étranger.', 'Éviscération : champ stérile humidifié, pas de compresses, ne pas réintégrer.', 'Femme enceinte + traumatisme violent = trauma abdominal.'],
  traps: ['Remettre les viscères en place.', 'Couvrir une éviscération avec des compresses sèches.'],
  quiz: [
    { q: 'Position d’une victime d’un traumatisme de l’abdomen sans détresse :', c: ['À plat dos, jambes fléchies', 'Assise', 'PLS', 'Jambes surélevées tendues'], e: 'PR Traumatisme de l’abdomen.', s: 'cat' },
    { q: 'Éviscération : que faire ?', c: ['Envelopper dans un champ stérile humidifié au sérum physiologique', 'Remettre les viscères en place', 'Couvrir de compresses sèches serrées', 'Laisser à l’air libre'], e: 'Sans mobiliser ni comprimer, pas de compresses.', s: 'cat' }
  ]
});

VSAV.chap({
  id: 'trauma-bassin', part: 'p2', seq: S21, title: 'Traumatisme du bassin et contention pelvienne', short: 'Trauma du bassin', motif: 'pelvis', accent: '#b45309',
  sources: ['PR - Traumatisme du bassin (MAJ 05/2024)', 'FT - Contention pelvienne (MAJ 05/2024)'],
  summary: 'Position allongée stricte, recherche de lésions, ceinture pelvienne si détresse circulatoire.',
  why: '<b>Pourquoi une ceinture ?</b> Une fracture du bassin peut saigner abondamment à l’intérieur (le bassin est une « boîte à sang »). La compression circonférentielle <b>rapproche les ailes iliaques</b>, immobilise les fragments et diminue le saignement (immobilisation + hausse de la pression intra-abdominale), surtout dans les fractures « en livre ouvert ».',
  sections: [
    { id: 'cat', t: 'Conduite à tenir (PR)', ic: 'list', src: 'PR - Traumatisme du bassin',
      steps: ['Laisser la victime en position allongée stricte si possible.', 'Dénuder le bassin en préservant l’intimité : plaies, hématomes, œdèmes, sang sur les sous-vêtements ; vérifier le bas du dos et les fesses lors de la mobilisation.', 'Traumatisme du bassin + signes de détresse circulatoire : contention externe après avis médical (sans avis possible : la mettre en place).', 'Protéger du froid, du vent ou de la chaleur.', 'Transmettre le bilan pour avis ; relever et immobiliser sur un MID selon les consignes.', 'Surveiller attentivement (aggravation brutale possible).'] },
    { id: 'ceinture', t: 'Poser la ceinture pelvienne', ic: 'pelvis', src: 'FT - Contention pelvienne',
      html: '<p><b>Quand :</b> avant le transport, après avis ou à la demande du médecin, ou si détresse circulatoire sans avis possible. Elle peut être <b>préinstallée</b> sous la victime dans l’attente de l’avis.</p>',
      steps: ['Glisser la ceinture sous les genoux de la victime allongée sur le dos.', 'Relever légèrement la victime (pont à plusieurs sauveteurs) pour décoller les fesses.', 'Glisser la ceinture sous les fesses et la centrer sur les grands trochanters ; reposer la victime.', 'Ramener les deux extrémités sur la symphyse en conservant un espace entre elles (extrémités repliables selon la taille).', 'Assurer la tension appropriée avec le dispositif de serrage (selon le type de ceinture).', 'Sécuriser la fermeture en « X » ou en « Z ». La ceinture reste en place jusqu’à l’hôpital.'],
      figs: [{ svg: 'pelvis', cap: 'Où passe la ceinture ?', txt: '<p>Appui latéral sur les grands trochanters, passage en avant sur la symphyse pubienne.</p>', src: 'FT - Contention pelvienne' }, { img: 'img/fiches/pelvienne.jpg', cap: 'Photos de la fiche technique', txt: '<p>Étapes réelles de la pose : passage sous les genoux, centrage sur les trochanters, écartement des extrémités, serrage.</p>', src: 'FT - Contention pelvienne, p. 2' }] }
  ],
  key: ['Position allongée stricte.', 'Ceinture si détresse circulatoire : après avis (sans avis possible : la poser).', 'Centrée sur les grands trochanters, fermée sur la symphyse.', 'Préinstallation possible ; reste en place à l’hôpital.', 'Immobilisation sur MID.'],
  traps: ['Placer la ceinture sur les crêtes iliaques (taille) au lieu des grands trochanters.', 'Retirer la ceinture à l’arrivée au VSAV.'],
  quiz: [
    { q: 'La ceinture pelvienne est centrée sur :', c: ['Les grands trochanters', 'Le nombril', 'Les crêtes iliaques', 'Les genoux'], e: 'FT Contention pelvienne.', s: 'ceinture' },
    { q: 'Quand poser une contention pelvienne sans avis médical ?', c: ['Traumatisme du bassin avec détresse circulatoire et avis impossible', 'Toujours', 'Jamais', 'Dès qu’il y a une douleur'], e: 'PR Traumatisme du bassin.', s: 'cat' },
    { q: 'Efficacité particulière de la ceinture :', c: ['Fractures « en livre ouvert »', 'Fractures du fémur', 'Entorses', 'Fractures du poignet'], e: 'FT Contention pelvienne.', s: 'ceinture' }
  ]
});

VSAV.chap({
  id: 'trauma-crane', part: 'p2', seq: S21, title: 'Traumatisme du crâne', short: 'Trauma du crâne', motif: 'brain', accent: '#9333ea',
  sources: ['PR - Traumatisme du crâne (MAJ 05/2024)'],
  summary: 'Tête en position neutre, retrait du casque, O₂ si besoin, surveillance du risque d’aggravation.',
  why: '<b>Pourquoi surveiller si étroitement ?</b> Une victime de traumatisme crânien peut paraître bien puis <b>s’aggraver brutalement</b>. Le rachis cervical peut être atteint en même temps : on maintient la tête en position neutre et on restreint les mouvements si besoin.',
  sections: [
    { id: 'cat', t: 'Conduite à tenir', ic: 'list', src: 'PR - Traumatisme du crâne',
      html: '<p>Perte de connaissance → conduite traumatisé inconscient qui respire. Consciente avec détresse vitale → conduite adaptée. <b>Sans détresse apparente :</b></p>',
      steps: ['Maintenir la tête en position neutre.', 'Retirer le casque de protection si la victime en porte un.', 'O₂ en inhalation si nécessaire.', 'Stabiliser ou restreindre les mouvements du rachis cervical si besoin.', 'Protéger du froid, de la chaleur ou des intempéries.', 'Transmettre un bilan, appliquer les consignes, surveiller (risque d’aggravation brutale).', 'Si immobilisation du rachis nécessaire : relevage adapté et matériel le plus adapté.'] }
  ],
  key: ['Tête en position neutre ; casque retiré.', 'O₂ si nécessaire.', 'Rachis : stabilisation / restriction si besoin.', 'Risque d’aggravation brutale → surveillance (Glasgow, pupilles).'],
  traps: ['Laisser repartir une victime « qui va bien » sans bilan transmis.'],
  quiz: [
    { q: 'Traumatisé crânien conscient sans détresse portant un casque :', c: ['Retirer le casque et maintenir la tête en position neutre', 'Laisser le casque en toutes circonstances', 'Le faire marcher', 'Le mettre en PLS'], e: 'PR Traumatisme du crâne.', s: 'cat' },
    { q: 'Pourquoi une surveillance attentive ?', c: ['Risque d’aggravation brutale', 'Pour la facturation', 'Ce n’est pas nécessaire', 'À cause de l’hypoglycémie'], e: 'PR Traumatisme du crâne.', s: 'cat' }
  ]
});

VSAV.chap({
  id: 'trauma-rachis', part: 'p2', seq: S21, title: 'Traumatisme du dos et du cou ; attelle cervicale X-Collar', short: 'Trauma du rachis', motif: 'neck', accent: '#c2410c',
  sources: ['PR - Traumatisme du dos et du cou (MAJ 05/2024)', 'FT - Attelle cervicale (X-Collar)'],
  summary: 'Stabilisation, restriction, immobilisation : quand et comment, critères A à E, choix du matériel.',
  why: '<b>Pourquoi tant de précautions ?</b> Une lésion de la colonne peut abîmer la <b>moelle épinière</b> qu’elle protège, avec des séquelles définitives (paralysie). Un mouvement intempestif peut créer ou aggraver la lésion. Mais l’immobilisation n’est jamais prioritaire sur une détresse vitale, et le collier n’est plus systématique : chaque outil a sa place.',
  sections: [
    { id: 'definitions', t: 'Stabiliser, restreindre, immobiliser', ic: 'neck', src: 'PR - Traumatisme du dos et du cou, p. 1',
      html: '<div class="tw"><table><tr><th>Terme</th><th>Définition</th><th>Moyens</th></tr><tr><td><b>Stabilisation</b></td><td>Maintien physique de la colonne en position neutre avant tout dispositif</td><td>Demander de ne pas bouger ; maintien de la tête à deux mains</td></tr><tr><td><b>Restriction</b> des mouvements du rachis cervical</td><td>Limitation des mouvements par un dispositif cervical</td><td>Blocs de tête, MID, collier cervical rigide</td></tr><tr><td><b>Immobilisation</b> de la colonne (corps entier)</td><td>Limiter tout mouvement de la colonne</td><td>Combinaison : blocs de tête, collier, plan dur, MID</td></tr></table></div>' },
    { id: 'priorite', t: 'La détresse vitale d’abord', ic: 'alert', src: 'PR - Traumatisme du dos et du cou, p. 1',
      html: '<p>Rechercher en priorité : hémorragie, obstruction des voies aériennes, détresse respiratoire, circulatoire, neurologique. À toutes les étapes, limiter les mouvements du rachis.</p><ul class="check"><li>Traumatisé <b>inconscient qui respire</b> : PLS à 2 sauveteurs ou plus, tête maintenue dans l’axe pendant la rotation (ne pas retirer un collier déjà en place).</li><li>Conscient : lui demander de ne pas bouger, stabiliser la tête ; blocs de tête possibles pour libérer le secouriste.</li><li>Avis médical.</li></ul>' },
    { id: 'criteres', t: 'Quand faut-il immobiliser ? Critères A à E', ic: 'clip', src: 'PR - Traumatisme du dos et du cou, p. 2–3',
      html: '<p>Hors détresse (ou après son traitement) : conseiller l’immobilité, stabiliser la tête si possible, retirer le casque, puis <b>immobilisation complète du rachis</b> si :</p><ul class="check"><li><b>(A) Réponses non fiables</b> : détresse vitale, altération de la conscience, non-coopération / difficultés de communication, alcool ou drogues, atteinte traumatique sévère.</li><li><b>(B) Signes d’atteinte du rachis</b> : douleur spontanée du rachis, douleur à la mobilisation ou à la marche, raideur de nuque empêchant de tourner la tête, douleur à la palpation prudente, déformation évidente.</li><li><b>(C) Signes d’atteinte de la moelle</b> : perte ou diminution de force / motricité des mains ou des pieds, de la sensibilité, engourdissement, décharges électriques (paresthésies), perte des urines ou des selles, érection chez l’homme (priapisme).</li><li><b>(D) Traumatisme à haut risque</b> + soit <b>plus de 65 ans</b>, soit <b>(E) antécédents à risque</b> : chute sur la tête &gt; 1 m (plongeon) ou sur les pieds / fesses &gt; 3 m ; passager d’un véhicule à grande vitesse (&gt; 40 km/h avec arrêt brutal, ou sur une courte distance &lt; 10 m, déformation de l’habitacle) ; absence de ceinture (et airbags déclenchés) ; retournement ; éjection ; véhicule de loisir à moteur (jet-ski, quad, kart) ; collision en 2 roues ; piéton renversé ; chute de cheval. (E) : traumatisme vertébral ancien, chirurgie de la colonne, maladie fragilisant colonne ou os (ostéoporose).</li></ul>',
      figs: [{ svg: 'rachis', cap: 'Arbre décisionnel simplifié', txt: '<p>Synthèse dessinée de la procédure. Les listes exactes A à E sont sur la fiche ci-dessous.</p>', src: 'PR - Traumatisme du dos et du cou' }, { img: 'img/fiches/rachis-criteres.jpg', cap: 'Critères (A) à (E) de la fiche', txt: '<p>Cases à cocher de la procédure départementale.</p>', src: 'PR - Traumatisme du dos et du cou, p. 3' }] },
    { id: 'cas', t: 'Cas particuliers', ic: 'list', src: 'PR - Traumatisme du dos et du cou, p. 4',
      html: '<ul class="check"><li><b>Plaie pénétrante isolée</b> du thorax, du cou ou de la tête : conduite de la plaie, <b>ne pas immobiliser</b>, avis médical.</li><li><b>Victime agitée, non coopérante</b> (alcool, enfant…) qui refuse : ne pas l’immobiliser, la laisser dans la position la plus confortable en essayant de maintenir la tête dans l’axe ; avis médical.</li><li><b>Déformation préexistante</b> (cyphose, scoliose) ou victime très âgée : respecter la position ; seul le MID le permet.</li><li><b>Enfant</b> : stabilisation en ligne si perte de connaissance ; aspiration en conservant la stabilisation ; le laisser dans son siège auto si la coque n’est pas déformée (rembourrage) ; brancard cuillère plutôt que plan dur ; MID (ou attelle à dépression pour les petits) qui reste jusqu’au brancard de l’hôpital ; plan dur réservé à l’extraction.</li></ul>' },
    { id: 'materiel', t: 'Choisir le moyen et la technique', ic: 'stretcher', src: 'PR - Traumatisme du dos et du cou, p. 5–7',
      html: '<ul class="check"><li><b>Collier cervical</b> : son usage systématique n’est plus conseillé. Encore utilisé pour l’extraction ou le relevage quand la stabilisation manuelle s’annonce difficile. Contre-indiqué si possible obstruction des voies aériennes ou déformation préexistante du rachis cervical. Doit être adapté, bien positionné, <b>desserré une fois la victime immobilisée dans le MID</b>, resserré pour une nouvelle mobilisation. Réévaluer les voies aériennes après la pose.</li><li><b>Immobilisation corps entier</b> : en priorité dans le <b>MID</b> (qui reste jusqu’au brancard de l’hôpital ; blocs de tête possibles dedans ; position adaptée possible, ex. demi-assise). Plan dur avec blocs de tête : exceptionnel (MID indisponible, secouristes insuffisants pour le transfert), sauf contre-indication.</li><li><b>Relevage d’une victime au sol</b> : brancard cuillère de préférence ; sinon pont à plusieurs ; sinon collier + plan dur par roulement au sol.</li><li><b>Endroit difficile d’accès</b> : extraction avec plan dur ou ACT ; collier + ACT si stabilisation difficile. Sans indication d’immobilisation : faire coopérer la victime, qui se dégage elle-même. Interrompre tout mouvement si la douleur ou les signes neurologiques s’aggravent.</li></ul>' },
    { id: 'xcollar', t: 'L’attelle cervicale X-Collar', ic: 'neck', src: 'FT - Attelle cervicale (X-Collar)',
      html: '<p>Posée <b>par deux secouristes</b> dès qu’une lésion du rachis cervical est suspectée (polytraumatisé, trauma crânien avec troubles de la vigilance, déficit neurologique, douleur cervicale post-traumatique, AVP à haute cinétique). Elle immobilise de C1 à C7 mais <b>doit être associée à un autre moyen</b> d’immobilisation. Taille unique, de <b>10–12 kg (≈ 3 ans) à 160 kg</b> ; radio-transparente ; réglages asymétriques possibles (tête en position de confort si elle ne peut être ramenée en neutre). Pas de mesure préalable ; pose par-dessus les vêtements sauf vêtement épais.</p>',
      steps: ['Mise en position neutre de la tête si possible (sinon position de confort) puis stabilisation du rachis.', 'Allonger le X-Collar au maximum, déplier et bloquer la partie arrière.', 'Victime allongée : se placer à droite, glisser la partie arrière à 45° jusqu’à la ligne médiane entre les omoplates, la redresser parallèlement aux épaules (mouvement de cisaillement).', 'Positionner le menton sur le rembourrage, fermer la boucle latérale.', 'Ajuster les 2 sangles velcro latérales blanches l’une après l’autre (principe d’opposition des forces : pousser – tirer), serrage modéré.', 'Ajuster la partie antérieure sur la poitrine (contact avec le sternum), la bloquer avec les 2 verrous.', 'Croiser et fixer les sangles colorées jaune et bleue sur les emplacements de même couleur.'],
      figs: [{ img: 'img/fiches/xcollar.jpg', cap: 'Pose du X-Collar (victime debout)', txt: '<p>Dessins de la fiche : boucle latérale, sangles blanches, partie antérieure, sangles croisées jaune / bleue.</p>', src: 'FT - Attelle cervicale (X Collar), p. 3' }],
      after: '<p><b>Efficacité :</b> contact avec le sternum et le menton en avant, le dos et la base de la tête en arrière, les mandibules latéralement. <b>BAVU :</b> desserrer uniquement la mentonnière (canule si nécessaire). Retrait seulement après avis médical.</p>' }
  ],
  key: ['Détresse vitale avant immobilisation ; limiter les mouvements à chaque étape.', 'Inconscient traumatisé qui respire : PLS à 2 ou plus, tête dans l’axe.', 'Immobiliser si A (non fiable), B (rachis), C (moelle), ou D (haut risque) + > 65 ans / E (antécédents).', 'Collier non systématique ; desserré une fois dans le MID.', 'MID en priorité ; brancard cuillère pour relever ; plan dur pour l’extraction.', 'Plaie pénétrante isolée tête / cou / thorax : pas d’immobilisation.', 'X-Collar : 2 secouristes, 10–12 kg à 160 kg, toujours associé à un autre moyen.'],
  memo: ['Stabiliser (mains) · restreindre (collier, blocs, MID) · immobiliser (corps entier)', 'Critères A non fiable · B rachis · C moelle · D haut risque + >65 ans ou E antécédents', 'Haut risque : chute tête > 1 m, pieds > 3 m, > 40 km/h, éjection, retournement…', 'MID prioritaire ; cuillère pour relever', 'Collier : non systématique, desserré dans le MID', 'Plaie pénétrante isolée : ne pas immobiliser'],
  traps: ['Poser un collier systématiquement à toute victime d’AVP.', 'Laisser le collier serré pendant tout le transport dans le MID.', 'Immobiliser de force une victime agitée qui refuse.', 'Utiliser le plan dur comme moyen de transport d’un enfant.'],
  quiz: [
    { q: 'La « restriction des mouvements du rachis cervical » se fait avec :', c: ['Un collier cervical, des blocs de tête ou le MID', 'Les mains du secouriste uniquement', 'Une écharpe', 'Un garrot'], e: 'La stabilisation = maintien manuel ; la restriction = dispositif.', s: 'definitions' },
    { q: 'Victime traumatisée inconsciente qui respire :', c: ['PLS à 2 sauveteurs ou plus, tête maintenue dans l’axe', 'Laisser sur le dos sans rien faire', 'PLS à 1 sauveteur', 'Position assise'], e: 'PR Traumatisme du dos et du cou.', s: 'priorite' },
    { q: 'Chute sur les pieds : à partir de quelle hauteur parle-t-on de traumatisme à haut risque ?', c: ['Plus de 3 m', 'Plus de 1 m', 'Plus de 10 m', 'Toute hauteur'], e: 'Chute sur la tête > 1 m ou sur les pieds / fesses > 3 m.', s: 'criteres' },
    { q: 'Le collier cervical, une fois la victime immobilisée dans le MID :', c: ['Doit être desserré', 'Doit être resserré au maximum', 'Doit être retiré par le secouriste', 'Doit être doublé'], e: 'Desserré une fois l’immobilisation sur le MID réalisée ; resserré pour une nouvelle mobilisation.', s: 'materiel' },
    { q: 'Plaie pénétrante isolée du cou :', c: ['Ne pas immobiliser, conduite de la plaie, avis médical', 'Collier cervical serré', 'Plan dur + sangles', 'MID systématique'], e: 'PR Traumatisme du dos et du cou, p. 4.', s: 'cas' },
    { q: 'Moyen recommandé pour relever un traumatisé du rachis allongé au sol :', c: ['Le brancard cuillère', 'Le plan dur par roulement', 'L’alèse portoir', 'La chaise de transport'], e: 'Brancard cuillère plutôt que plan dur ; à défaut pont à plusieurs.', s: 'materiel' },
    { q: 'Le X-Collar est utilisable à partir de :', c: ['10–12 kg (environ 3 ans)', 'La naissance', '30 kg', '15 ans'], e: 'FT X-Collar : 10–12 kg jusqu’à 160 kg.', s: 'xcollar' },
    { q: 'Pendant une ventilation au BAVU, avec un X-Collar en place :', c: ['Desserrer uniquement la mentonnière', 'Retirer l’attelle', 'Desserrer toutes les sangles', 'Ne rien toucher, ventiler en force'], e: 'FT X-Collar : risques.', s: 'xcollar' }
  ]
});

VSAV.chap({
  id: 'trauma-thorax', part: 'p2', seq: S21, title: 'Traumatisme du thorax', short: 'Trauma du thorax', motif: 'lungs', accent: '#dc2626',
  sources: ['PR - Traumatisme du thorax (MAJ 05/2024)'],
  summary: 'Position assise si gêne respiratoire, plaie protégée par un dispositif non occlusif, jamais de retrait de corps étranger.',
  why: '<b>Pourquoi un pansement non occlusif ?</b> Une plaie du thorax peut laisser entrer de l’air dans la cage thoracique (« plaie soufflante »). Un dispositif occlusif empêcherait cet air de ressortir. La fiche demande un <b>dispositif non occlusif spécifique</b> ; à défaut, <b>laisser la plaie à l’air libre</b>.',
  sections: [
    { id: 'cat', t: 'Conduite à tenir', ic: 'list', src: 'PR - Traumatisme du thorax',
      html: '<p>Perte de connaissance → conduite traumatisé inconscient qui respire. Détresse vitale consciente → détresse respiratoire ou circulatoire. <b>Sans détresse apparente :</b></p>',
      steps: ['Position assise ou demi-assise dès qu’il existe une gêne respiratoire, maintenue au relevage et au transport.', 'Dénuder le thorax en préservant l’intimité et sans exposer au froid.', 'Vérifier le dos, notamment lors de la mobilisation (position assise, PLS).', 'O₂ en inhalation si nécessaire.', 'Protéger la plaie par un dispositif médical non occlusif spécifique ; à défaut, laisser à l’air libre.', 'Protéger du froid, du vent, de la chaleur ; bilan pour avis ; surveiller (aggravation brutale).'],
      after: '<div class="callout bad"><b>Corps étranger</b>Ne jamais retirer un corps étranger pénétrant dans le thorax, sauf s’il empêche la réalisation d’une RCP.</div>' }
  ],
  key: ['Gêne respiratoire → assise ou demi-assise, gardée au transport.', 'Plaie : dispositif non occlusif, sinon à l’air libre.', 'Corps étranger : jamais retiré (sauf s’il empêche la RCP).', 'Toujours vérifier le dos.'],
  traps: ['Fermer une plaie thoracique avec un pansement étanche.', 'Allonger à plat une victime qui respire mal.'],
  quiz: [
    { q: 'Plaie thoracique sans dispositif spécifique disponible :', c: ['La laisser à l’air libre', 'La fermer avec un film étanche', 'Comprimer fortement', 'Mettre de la glace'], e: 'PR Traumatisme du thorax.', s: 'cat' },
    { q: 'Seule exception au maintien d’un corps étranger dans le thorax :', c: ['Il empêche la réalisation d’une RCP', 'Il est petit', 'La victime le demande', 'Il saigne peu'], e: 'Ne jamais retirer sauf s’il empêche la RCP.', s: 'cat' },
    { q: 'Traumatisé du thorax avec gêne respiratoire : position ?', c: ['Assise ou demi-assise', 'À plat dos', 'Tête basse', 'Sur le ventre'], e: 'Maintenue lors du relevage et du transport.', s: 'cat' }
  ]
});

VSAV.chap({
  id: 'trauma-face', part: 'p2', seq: S21, title: 'Traumatisme de la face et de la face antérieure du cou', short: 'Trauma face et cou', motif: 'eye', accent: '#e11d48',
  sources: ['PR - Traumatisme de la face et de la face antérieure du cou (MAJ 05/2024)'],
  summary: 'Plaie grave par définition, œil, dents, fractures de la face.',
  why: '<b>Pourquoi « grave par principe » ?</b> Une plaie de la face ou du cou, hors éraflure, est considérée grave du fait de sa localisation : voies aériennes, gros vaisseaux, yeux. Les fractures de la face saignent abondamment et le sang peut encombrer les voies aériennes : d’où la position sur le côté.',
  sections: [
    { id: 'plaie', t: 'Plaie de la face ou du cou', ic: 'drop', src: 'PR - Traumatisme de la face et du cou',
      html: '<ul class="check"><li>Saignement abondant : compression manuelle ; au cou, <b>ne pas comprimer la trachée</b> ; maintenir la compression ou pansement compressif d’urgence avec <b>contre-appui sous le bras opposé</b>.</li><li>Laisser les corps étrangers en place même transfixiants, sauf s’ils obstruent les voies aériennes.</li></ul>' },
    { id: 'oeil', t: 'Œil, dents, fractures', ic: 'eye', src: 'PR - Traumatisme de la face et du cou',
      html: '<div class="tw"><table><tr><th>Atteinte</th><th>Conduite</th></tr><tr><td>Œil</td><td>Minimiser les mouvements des yeux : ne pas bouger, fermer les yeux, à plat dos si possible ; recouvrir sans appuyer les <b>deux yeux</b> de compresses stériles (seulement s’il n’y a pas de corps étranger) ; ne jamais retirer un corps étranger oculaire</td></tr><tr><td>Dents</td><td>Conduite face à une plaie</td></tr><tr><td>Fracture de la face (mandibule, maxillaire, nez)</td><td>Installer sur le côté ; conduite détresse respiratoire si nécessaire ; traumatisme mineur → conduite saignement de nez</td></tr></table></div><p>Dans tous les cas : perte de connaissance → conduite adaptée ; avis médical.</p>' }
  ],
  key: ['Plaie face / cou = plaie grave (sauf éraflure).', 'Cou : ne pas comprimer la trachée ; contre-appui sous le bras opposé.', 'Œil : couvrir les deux yeux sans appuyer ; ne jamais retirer un corps étranger.', 'Fracture de la face : victime sur le côté.'],
  traps: ['Ne couvrir que l’œil blessé (les yeux bougent ensemble).', 'Retirer un corps étranger planté dans la joue alors qu’il ne gêne pas la respiration.'],
  quiz: [
    { q: 'Traumatisme d’un œil : on recouvre…', c: ['Les deux yeux, sans appuyer', 'Uniquement l’œil blessé, en comprimant', 'Rien du tout', 'L’œil sain uniquement'], e: 'Minimiser les mouvements oculaires.', s: 'oeil' },
    { q: 'Pansement compressif d’une plaie du cou : contre-appui ?', c: ['Sous le bras opposé', 'Sur la trachée', 'Sur le front', 'Sur le menton'], e: 'Ne pas comprimer la trachée ; contre-appui sous le bras opposé.', s: 'plaie' },
    { q: 'Fracture de la mâchoire qui saigne : position ?', c: ['Sur le côté', 'À plat dos tête en arrière', 'Assise tête penchée en arrière', 'Debout'], e: 'Le sang peut encombrer les voies aériennes.', s: 'oeil' }
  ]
});

VSAV.chap({
  id: 'immobilisation', part: 'p2', seq: S21, title: 'Immobilisation générale : MID et plan dur', short: 'MID et plan dur', motif: 'stretcher', accent: '#ea580c',
  sources: ['FT - Immobilisation générale sur un matelas à dépression (MID)', 'FT - Immobilisation générale sur un plan dur (MAJ 05/2024)'],
  summary: 'Le MID, moyen prioritaire ; le plan dur, outil d’extraction et solution de repli.',
  why: '<b>Pourquoi le MID d’abord ?</b> En faisant le vide, les billes se solidarisent et le matelas <b>moule</b> la victime : axe tête-cou-tronc respecté, membres inférieurs immobilisés, position adaptée possible (demi-assise), et il reste en place jusqu’au brancard de l’hôpital. Le plan dur est rigide mais ne moule pas : c’est d’abord un outil d’<b>extraction</b>.',
  sections: [
    { id: 'mid', t: 'Le matelas immobilisateur à dépression (MID)', ic: 'stretcher', src: 'FT - Immobilisation générale sur un MID',
      html: '<p>Indiqué pour la suspicion de traumatisme de la colonne, du bassin ou de la cuisse, surtout en cas de lésions multiples. Installation par brancard cuillère, pont à 4 porteurs, exceptionnellement plan dur.</p>',
      steps: ['Placer le MID près de la victime (surface plane et dure si possible, bâche dessous si besoin).', 'Ouvrir le robinet pour répartir les billes ; rigidifier modérément en relevant les côtés ; mettre un drap ou une couverture de survie.', 'Déposer la victime ; retirer systématiquement le dispositif de portage.', 'Mettre en forme : rapprocher les bords de part et d’autre de la tête (le secouriste replace ses mains à l’extérieur) ; le matelas ne doit jamais appuyer sur le sommet du crâne.', 'Maintenir les bords le long de la victime avec les sangles.', 'Faire le vide jusqu’à ce que le matelas soit dur ; fermer le robinet, déconnecter.', 'Ajuster les sangles ; relâcher un collier cervical rigide éventuel.'],
      after: '<ul class="trap"><li>Surveiller la rigidité en permanence (piqûre, déchirure).</li><li>Transport sur un dispositif de portage (brancard, plan dur, cuillère, barquette) ; seul, uniquement sur quelques mètres en le soutenant sur les côtés.</li><li>Il peut masquer un saignement.</li></ul><p><b>Efficacité :</b> aucun mouvement possible, pas de glissement, sangles ne gênant pas la respiration, pas de contact avec le haut du crâne.</p>' },
    { id: 'plandur', t: 'Le plan dur', ic: 'stretcher', src: 'FT - Immobilisation générale sur un plan dur',
      html: '<p><b>Quand :</b> extraction d’un endroit difficile d’accès ; immobilisation en l’absence de MID ; allonger une victime suspecte retrouvée <b>debout</b>. Environ <b>1,85 m</b>, PVC radio-transparent, poignées, sangles (thorax, bassin, membres inférieurs) ; immobilisateur de tête (coussin, 2 blocs, sangles front et menton).</p><p>Victime sur le dos : brancard cuillère = référence ; sinon pont à 4 ; sinon roulement au sol à 3 (risque de mobilisation plus élevé). Contrôler motricité et sensibilité avant et après.</p>',
      steps: ['S1 maintient la tête pendant toute la manœuvre et commande ; collier posé.', 'S2 ou 3 : mains de la victime sur ses cuisses (jamais le bras côté retournement au-dessus de la tête) ; membres inférieurs dans l’axe.', 'Rembourrage de 3 à 4 cm contre la victime côté retournement ; plan dur (coussin de tête en place) le long du côté opposé.', 'S2 et S3 à genoux côté retournement, saisissent épaule, bassin, membres inférieurs alignés.', 'S1 : « Êtes-vous prêts ? » — « Prêts ! » — « Attention pour tourner… Tournez ! » : rotation lente, d’un bloc, bras tendus, arrêtée sur le côté ; S1 garde la tête dans l’axe.', 'S2 et S3 examinent le dos. S1 : « Glissez le plan dur ! » (incliné pour se plaquer contre la victime).', 'S1 : « Attention pour poser… Posez ! » ; recentrer la victime en maintenant l’axe.', 'Solidariser : sangle-araignée ou sangles (haut du thorax, bassin, cuisses au-dessus des genoux) ; blocs de tête puis sangles frontale et mentonnière ; contrôler motricité et sensibilité.'], stepsTitle: 'Roulement au sol à 3 (victime sur le dos)',
      after: '<p><b>Victime debout</b> (3 intervenants, S2 derrière commande) : collier, plan dur contre le dos, S1 et S3 passent un bras sous les aisselles et saisissent la poignée la plus haute ; « Attention pour basculer… Basculez ! » : on allonge en basculant, tête au contact du plan dur. Victime casquée debout : manœuvre casque en place, retrait du casque une fois allongée, puis collier si nécessaire.</p><p><b>Transfert plan dur → MID :</b> pont à 4 + une 5e personne retirant le plan dur, ou brancard cuillère à 3 ; sinon transport sur le plan dur. Sangles thoraciques trop serrées : aggravation d’une détresse respiratoire.</p>' }
  ],
  key: ['MID = immobilisation corps entier prioritaire ; reste jusqu’à l’hôpital.', 'MID : jamais d’appui sur le sommet du crâne ; retirer le dispositif de portage ; relâcher le collier.', 'Plan dur ≈ 1,85 m : extraction, repli sans MID, victime debout.', 'Rotation d’un bloc sur ordre du secouriste de tête ; examen du dos.', 'Sangles : haut du thorax, bassin, cuisses au-dessus des genoux.'],
  traps: ['Laisser le plan dur ou le brancard cuillère sous la victime dans le MID.', 'Matelas contre le sommet du crâne : à la mise sous vide, il fléchit la tête.', 'Porter le MID seul sur une longue distance.'],
  quiz: [
    { q: 'Le MID ne doit jamais être au contact :', c: ['Du sommet du crâne', 'Des épaules', 'Des talons', 'Du dos'], e: 'L’aspiration entraînerait par rétraction une flexion de la tête.', s: 'mid' },
    { q: 'Une fois la victime immobilisée dans le MID, le collier cervical rigide :', c: ['Est relâché', 'Est serré davantage', 'Est remplacé par un plan dur', 'Est retiré par le secouriste et jeté'], e: 'FT MID : celui-ci doit être relâché.', s: 'mid' },
    { q: 'Technique de référence pour installer sur un plan dur une victime allongée sur le dos :', c: ['Le brancard cuillère', 'Le roulement au sol', 'L’alèse portoir', 'La chaise de transport'], e: 'À défaut : pont à 4 porteurs ; en dernier recours : roulement à 3.', s: 'plandur' },
    { q: 'Où passent les sangles d’immobilisation sur le plan dur ?', c: ['Haut du thorax, bassin, cuisses juste au-dessus des genoux', 'Cou, ventre, chevilles', 'Uniquement le thorax', 'Tête et pieds'], e: 'Ou sangle-araignée.', s: 'plandur' },
    { q: 'Qui commande la manœuvre de roulement sur plan dur ?', c: ['Le secouriste qui maintient la tête (S1)', 'Le secouriste aux pieds', 'La victime', 'Le conducteur'], e: 'S1 guide et commande l’ensemble de la manœuvre.', s: 'plandur' }
  ]
});

VSAV.chap({
  id: 'act', part: 'p2', seq: S22, title: 'L’attelle cervico-thoracique (ACT) : pose et retrait', short: 'ACT pose et retrait', motif: 'neck', accent: '#d97706',
  sources: ['FT - Pose de l’attelle cervico-thoracique (ACT)', 'FT - Retrait de l’ACT pour immobilisation sur MID (MAJ 05/2024)'],
  summary: 'Immobiliser tête, nuque et dos d’une victime assise pour l’extraire, puis retirer l’ACT dans le MID.',
  why: '<b>Pourquoi la retirer ?</b> L’ACT sert à <b>extraire</b>, pas à transporter : sangles serrées, elle limite les mouvements de la cage thoracique (aggravation d’une détresse respiratoire) et une immobilisation prolongée peut léser la peau (brûlure, escarre). On la retire une fois la victime allongée sur le MID, <b>avant</b> de rigidifier le matelas.',
  sections: [
    { id: 'pose', t: 'Pose de l’ACT (3 intervenants)', ic: 'neck', src: 'FT - Pose de l’attelle cervico-thoracique',
      html: '<p>Composition : corset semi-rigide avec rabat de tête, 3 sangles thoraciques, 2 sangles de cuisses, poignées de portage, coussin de tête, sangles front / menton, sac. Posée <b>après la restriction du rachis cervical</b>.</p>',
      steps: ['S1 (de préférence derrière la victime) maintient la tête à deux mains pendant toute la manœuvre ; S2 et S3 de part et d’autre.', 'S2 ou S3 contrôle motricité et sensibilité des extrémités (si non fait au bilan).', 'S2 et S3 décollent légèrement la victime du dossier (maintien antéro-postérieur, axe tête-cou-tronc) et examinent le dos.', 'S2 maintient la victime ; S3 insère l’ACT, extrémité de la tête en premier, entre le dos et le dossier sans toucher les avant-bras de S1.', 'S2 et S3 centrent l’ACT sur la colonne, ramènent la victime contre elle, glissent les parties mobiles sous les bras (contact avec les aisselles).', 'Attacher les sangles thoraciques : celle du milieu, puis l’inférieure, puis la supérieure.', 'Passer les sangles de cuisses sous les cuisses (croisement devant le pubis possible si pas de trauma du bassin ; pas de sangle du côté d’une fracture du fémur).', 'Serrer l’ensemble ; combler l’espace derrière la tête avec le coussin plié.', 'Sangles de tête : l’une sur le front, l’autre sous le menton sur la partie haute et rigide du collier (S1 déplace ses doigts).', 'Ajuster sans comprimer le thorax ; contrôler motricité et sensibilité ; le maintien de la tête peut être relâché.'],
      after: '<ul class="trap"><li>Enfant : couverture roulée devant thorax et abdomen si l’ACT est trop grande.</li><li>Fin de grossesse : ne pas serrer la sangle inférieure sur l’abdomen.</li><li>Traumatisme du thorax : sangle supérieure pas trop serrée.</li></ul>' },
    { id: 'retrait', t: 'Retrait de l’ACT dans le MID', ic: 'list', src: 'FT - Retrait de l’ACT',
      html: '<p>Trois techniques : <b>à 3 secouristes sans matériel</b>, <b>pont amélioré à 4 porteurs + 1 personne qui retire l’ACT</b>, <b>brancard cuillère</b> (relevage en intégrant ACT et victime, puis retrait par un secouriste qui libère une main, une personne en plus, ou lors d’un transfert de dispositif).</p>',
      steps: ['S2 et S3 détachent les sangles de cuisses, les font glisser sans vrille vers la tête, sous l’ACT, pour s’en servir de poignées de traction.', 'S1, à genoux dans l’axe, stabilise la tête (prise latéro-latérale).', 'S2 et S3 enlèvent les sangles de tête, détachent les sangles thoraco-abdominales et les placent le long des membres inférieurs.', 'S2 relaie le maintien de tête ; S1 se met en pont jambes écartées et reprend la stabilisation latéro-latérale.', 'S3 en pont face à S1 saisit les épaules ; S2 derrière S1 saisit les deux sangles de cuisses.', 'Sur ordre de S1, S1 et S3 décollent légèrement tête et épaules ; S2 tire progressivement, sans à-coups, et retire l’ACT.', 'S2 relaie la tête ; S1 reprend la stabilisation à genoux ; terminer le conditionnement dans le MID.'], stepsTitle: 'Retrait à 3 secouristes sans matériel' }
  ],
  key: ['ACT posée après restriction du rachis cervical, à 3 intervenants.', 'Sangles thoraciques : milieu, inférieure, supérieure.', 'Pas de sangle de cuisse côté fracture du fémur.', 'Sangle de menton sur la partie rigide du collier.', 'L’ACT n’est pas un moyen de transport : retirée sur le MID avant de le rigidifier.'],
  traps: ['Rigidifier le MID avec l’ACT encore en place.', 'Serrer la sangle inférieure sur le ventre d’une femme enceinte en fin de grossesse.'],
  quiz: [
    { q: 'Ordre de fermeture des sangles thoraciques de l’ACT :', c: ['Milieu, puis inférieure, puis supérieure', 'Supérieure, milieu, inférieure', 'Inférieure, supérieure, milieu', 'Peu importe'], e: 'FT Pose de l’ACT.', s: 'pose' },
    { q: 'Suspicion de fracture du fémur droit lors de la pose de l’ACT :', c: ['Ne pas placer la sangle de la cuisse droite', 'Serrer davantage la sangle droite', 'Croiser les sangles', 'Ne pas poser d’ACT'], e: 'La sangle de la cuisse correspondante ne doit pas être placée.', s: 'pose' },
    { q: 'Quand retire-t-on l’ACT ?', c: ['Une fois la victime allongée sur le MID, avant de le rigidifier', 'À l’hôpital', 'Avant l’extraction', 'Jamais'], e: 'L’ACT n’est pas un moyen d’immobilisation pour le transport.', s: 'retrait' },
    { q: 'Retrait à 3 sans matériel : que tire S2 ?', c: ['Les deux sangles de cuisses', 'La tête de la victime', 'Le coussin de tête', 'Les sangles thoraciques'], e: 'Les sangles de cuisses glissées sous l’ACT servent de moyen de traction.', s: 'retrait' }
  ]
});

VSAV.chap({
  id: 'boa', part: 'p2', seq: S22, title: 'L’attelle d’extraction BOA et les plans durs concaves', short: 'BOA et plan dur concave', motif: 'car', accent: '#ea580c',
  sources: ['FT - Une attelle d’extraction pour espaces confinés BOA (MAJ 05/2024)', 'FT - Extraction de véhicule avec plan dur concave et BOA (MAJ 05/2024)'],
  summary: 'Extraction rapide d’une victime incarcérée, dans tous les axes, avec un minimum de contrainte sur le tronc.',
  why: '<b>Pourquoi le BOA ?</b> Mise en place rapide, sans constriction du tronc, il permet d’extraire ou de relever une victime d’un environnement où le travail traditionnel est impossible, en respectant les gestes et postures des secouristes. Mais ses tractions peuvent donner des <b>paresthésies</b> des membres supérieurs : on ne tire dessus <b>qu’au moment de l’extraction</b>, et la durée doit être la plus brève possible.',
  sections: [
    { id: 'boa', t: 'Le BOA', ic: 'neck', src: 'FT - Attelle d’extraction BOA',
      html: '<p>Victime traumatisée ou non, adulte ou enfant de <b>plus de 1,50 m</b>, à la diligence du chef d’agrès. <b>Restriction du rachis obligatoire au préalable</b> (collier ou attelle cervicale) ; sur une victime non traumatisée, le collier reste obligatoire pour éviter la <b>strangulation</b>. Interdit si un corps étranger est sur le passage du BOA.</p>',
      steps: ['Équipier 1 : poursuit la stabilisation de la tête en position neutre (inutile si non traumatisée, mais collier obligatoire).', 'Équipier 2 : présente le BOA, pointe du triangle rouge du logo devant le larynx.', 'Équipier 2 : ramène les extrémités sur les épaules, les croise au niveau des cervicales, les ramène vers l’avant avec une légère traction.', 'Équipier 2 : passe les extrémités sous les aisselles correspondantes.', 'Équipier 1 : récupère les poignées, mains dans les dragonnes, saisit le BOA juste au-dessus des épaules ; stabilise la tête via le BOA sans tension.', 'Équipier 2 : prépare les plans durs concaves (traumatisé) et le brancard dans l’axe de sortie.'],
      figs: [{ img: 'img/fiches/boa-pose.jpg', cap: 'Pose du BOA (photos et dessins de la fiche)', txt: '<p>Triangle rouge devant le larynx, croisement derrière la nuque, passage sous les aisselles.</p>', src: 'FT - Attelle d’extraction type BOA, p. 2' }] },
    { id: 'extraction', t: 'Extraction avec plans durs concaves + BOA (5 intervenants)', ic: 'car', src: 'FT - Extraction de véhicule avec plan dur concave et BOA',
      html: '<p>Kit de 3 plans durs concaves (demi-plan dur, plan dur adulte, plan dur enfant). Sortie possible dans tous les axes (0°, 30°, 60°, 90°), plan de confort ou sortie rapide.</p>',
      steps: ['S1 : maintien tête. S2 : attelle cervicale, puis BOA sans tension.', 'S1 : lâche la stabilisation et reprend le BOA par ses poignées. S2 : maintien antéro-postérieur (thorax et omoplates).', 'S3 : contrôle le dos, baisse le siège pour engager le demi-plan dur contre le dos.', 'S1 : maintient l’ensemble BOA + demi-plan dur ; S3 finalise l’abaissement du siège.', 'S4 : engage le plan dur jusqu’au bas du demi-plan dur et le maintient. S2 : maintien du bassin sans appuyer. S5 : aux jambes pour les faire suivre.', 'S1 : abaisse l’ensemble demi-plan dur / BOA sur le plan dur et le fait glisser (planches incurvées). S4 : abaisse le plan dur au fur et à mesure.', 'S3 : reprend le BOA depuis l’extérieur ; S1 reprend le bassin, S2 les jambes, jusqu’à la victime entièrement sur le plan dur.', 'S4 et S5 : mettent le plan dur à l’horizontale ; S2 et S5 brancardent jusqu’au MID. Relais si nécessaire.'],
      after: '<div class="callout bad"><b>Avant d’immobiliser</b>Le BOA et les plans durs concaves doivent être enlevés. Le BOA n’est pas un moyen d’immobilisation pour le transport.</div>',
      figs: [{ img: 'img/fiches/boa-extraction-1.jpg', cap: 'Extraction : mise en place (photos de la fiche)', txt: '', src: 'FT - Extraction avec plan dur concave et BOA, p. 2' }, { img: 'img/fiches/boa-extraction-2.jpg', cap: 'Extraction : glissement sur le plan dur', txt: '', src: 'FT - Extraction avec plan dur concave et BOA, p. 3' }] }
  ],
  key: ['BOA : victime > 1,50 m ; restriction du rachis préalable obligatoire.', 'Non traumatisée : collier obligatoire (risque de strangulation).', 'Triangle rouge devant le larynx ; croisé derrière la nuque ; sous les aisselles.', 'Traction seulement pendant l’extraction (paresthésies) ; durée la plus brève.', 'Plans durs concaves : extraction à 5, tous axes ; tout retirer avant l’immobilisation.'],
  traps: ['Exercer une tension continue sur les poignées du BOA en attendant l’extraction.', 'Utiliser le BOA chez un enfant de moins de 1,50 m.', 'Transporter la victime dans le BOA.'],
  quiz: [
    { q: 'Taille minimale de la victime pour le BOA :', c: ['1,50 m', '1,20 m', '1,80 m', 'Aucune'], e: 'FT BOA : victimes de plus de 150 cm.', s: 'boa' },
    { q: 'Victime non traumatisée relevée avec le BOA :', c: ['Le collier reste obligatoire pour éviter une strangulation', 'Pas de collier nécessaire', 'Stabilisation de la tête obligatoire en continu', 'BOA interdit'], e: 'FT BOA.', s: 'boa' },
    { q: 'Pourquoi ne tirer sur le BOA qu’au moment de l’extraction ?', c: ['Risque de paresthésies des membres supérieurs', 'Risque de casser le BOA', 'Pour économiser l’énergie', 'Pour ne pas réveiller la victime'], e: 'FT BOA : risques.', s: 'boa' },
    { q: 'Combien d’intervenants pour l’extraction avec plans durs concaves + BOA ?', c: ['5', '2', '3', '7'], e: 'FT Extraction de véhicule avec plan dur concave et BOA.', s: 'extraction' }
  ]
});

VSAV.chap({
  id: 'sorties', part: 'p2', seq: S23, title: 'Les sorties de véhicule : latérale, oblique, arrière', short: 'Sorties de véhicule', motif: 'car', accent: '#c2410c',
  sources: ['FT - Sortie latérale d’une victime', 'FT - Sortie oblique d’une victime', 'FT - Sortie arrière d’une victime (MAJ 05/2024)'],
  summary: 'Victime assise immobilisée dans l’ACT : choisir l’axe de sortie et coordonner le « soulager – glisser ».',
  why: '<b>Pourquoi plusieurs sorties ?</b> Le choix dépend de l’état du véhicule et des lésions : la latérale est rapide mais interdite si bassin ou fémur atteints ; l’arrière protège mieux l’axe pour les atteintes majeures ; l’oblique sert quand l’arrière est impossible. Dans tous les cas, la victime est d’abord immobilisée dans l’<b>ACT</b> et la manœuvre est guidée par le chef d’agrès.',
  sections: [
    { id: 'choix', t: 'Choisir la sortie', ic: 'car', src: 'FT Sorties latérale, oblique, arrière',
      figs: [{ anim: 'sorties', cap: 'Animation : les trois axes de sortie (vue de dessus)', txt: '<p>Change de technique pour voir le trajet de la victime et le positionnement du plan dur.</p>', src: 'FT Sorties latérale / oblique / arrière' }],
      html: '<div class="tw"><table><tr><th>Sortie</th><th>Indication</th><th>Équipe</th><th>Matériel</th></tr><tr><td>Latérale</td><td>Véhicule peu déformé ; atteinte du rachis <b>sans perte de motricité ni de sensibilité</b>. <b>Proscrite</b> si bassin ou fémur atteints</td><td>3 + 1 (5e possible)</td><td>X-Collar, ACT, plan dur + sangle araignée</td></tr><tr><td>Oblique</td><td>Extraction par l’arrière impossible, après découpe du montant central côté victime (à défaut à l’opposé)</td><td>4 minimum (5e possible)</td><td>X-Collar, ACT, plan dur sans immobilisateur de tête + araignée</td></tr><tr><td>Arrière</td><td>Dégagement latéral impossible ou atteintes majeures (fémur, bassin, rachis…) ; toit pas obligatoirement retiré</td><td>5 minimum</td><td>Collier ou X-Collar, ACT, plan dur</td></tr></table></div>' },
    { id: 'laterale', t: 'Sortie latérale', ic: 'list', src: 'FT - Sortie latérale d’une victime',
      steps: ['S1 : introduit le plan dur par la portière opposée au siège de la victime.', 'S2 et 3 : soulèvent légèrement la victime par les poignées de l’ACT et les cuisses.', 'S1 : insère le plan dur sous les fesses jusqu’au seuil extérieur de porte côté victime, le maintient (dégage les pieds des pédales si besoin).', 'S2 et 3 : font pivoter la victime par les poignées de l’ACT et l’allongent sur le plan dur.', 'S2 et 3 (éventuellement 4 au bassin) : hissent la victime jusqu’en haut du plan dur par « soulager – glisser ».', 'S1, 2, 3 : extraient du côté le plus pratique ; 2 et 3 sortent successivement pour accompagner ; sangle araignée ; conditionnement dans le MID.'] },
    { id: 'arriere', t: 'Sortie arrière', ic: 'list', src: 'FT - Sortie arrière d’une victime',
      steps: ['S1 : maintient la victime assise par l’ACT. S3 : abaisse le dossier au maximum.', 'S2 : engage le plan dur par l’arrière, dans l’axe, jusqu’à buter contre la victime (le plus bas possible) et le maintient (contre le dos si toit retiré, sinon le plus relevé possible).', 'S4 : dégage et maintient les pieds.', 'S1 et 3 : allongent la victime sur le plan dur.', 'S1, 3, 4, 5 : hissent la victime en haut du plan dur par « soulager – glisser » (poignées de l’ACT et cuisses ; S5 soulage le bassin), puis mettent le plan dur à l’horizontale.', 'S1 et 3 sortent successivement ; tous extraient la victime, déposent le plan dur, immobilisent après retrait du matériel d’extraction.'],
      after: '<p><b>Commandements :</b> chef d’agrès <span class="cmd">« Soulager »</span> : on soulage le poids sans décoller la victime du plan dur ; <span class="cmd">« Glisser »</span> : on glisse la victime vers le haut du plan dur. Pour l’oblique, c’est S2 qui donne ces ordres.</p><div class="callout bad"><b>Règle de sécurité commune</b>Ne jamais prendre appui sur la victime ou sur un équipier en contact avec elle pour se positionner.</div>' }
  ],
  key: ['Victime immobilisée dans l’ACT avant toute sortie ; le sauveteur de tête peut alors se retirer.', 'Latérale : 3 + 1, interdite si bassin / fémur.', 'Oblique : 4 minimum, après découpe du montant central.', 'Arrière : 5 minimum, atteintes majeures.', '« Soulager » puis « Glisser ».', 'Jamais d’appui sur la victime ou un équipier.'],
  traps: ['Choisir la sortie latérale pour une fracture du bassin.', 'Décoller la victime du plan dur au commandement « soulager ».'],
  quiz: [
    { q: 'Quelle sortie est proscrite en cas d’atteinte du bassin ou du fémur ?', c: ['La sortie latérale', 'La sortie arrière', 'La sortie oblique', 'Aucune'], e: 'FT Sortie latérale.', s: 'choix' },
    { q: 'Nombre minimal d’équipiers pour la sortie arrière :', c: ['5', '3', '4', '2'], e: 'FT Sortie arrière : 5 équipiers secouristes minimum.', s: 'choix' },
    { q: 'Au commandement « Soulager », les équipiers :', c: ['Soulagent le poids sans décoller la victime du plan dur', 'Soulèvent la victime au-dessus du plan dur', 'Lâchent la victime', 'Glissent la victime vers le haut'], e: 'Puis « Glisser » : glisser vers le haut du plan dur.', s: 'arriere' },
    { q: 'La sortie oblique se fait :', c: ['Après découpe du montant central côté victime (à défaut à l’opposé)', 'Par le coffre', 'Par le toit uniquement', 'Sans découpe'], e: 'FT Sortie oblique.', s: 'choix' }
  ]
});

VSAV.chap({
  id: 'extraction-sr', part: 'p2', seq: S23, title: 'Procédure d’extraction et d’immobilisation en secours routier', short: 'Procédure SR', motif: 'road', accent: '#9a3412',
  sources: ['PR - Extraction et immobilisation de la victime en SR au VSAV (SDIS 51 / GFOR / Pôle SUAP, MAJ 12-2023)'],
  summary: 'L’arbre de décision du secours routier : assise ou allongée, ACT, BOA ou plan dur, puis MID.',
  why: '<b>Pourquoi anticiper ?</b> La victime doit être <b>mobilisée le moins possible</b> : le chef d’agrès choisit la méthode de relevage et d’immobilisation <b>avant</b> l’extraction. Quand la victime doit être hissée, la stabilisation manuelle devient difficile : on la supplée par du matériel (ACT, BOA, plan dur concave) en plus du collier ou du X-Collar.',
  sections: [
    { id: 'arbre', t: 'L’arbre de décision', ic: 'road', src: 'PR - Extraction et immobilisation en SR',
      steps: ['Gestes de survie initiés tout au long de la prise en charge ; stabilisation du rachis cervical.', 'Immobilisation du rachis recommandée selon l’arbre décisionnel « bilan traumatique du rachis » ? NON : relâcher la stabilisation et accompagner prudemment la victime hors du véhicule.', 'OUI : restriction du rachis cervical.', 'Victime assise (extraction possible à 0°, 30°, 60°, 90°) : la stabilisation devient difficile → la suppléer par du matériel : ACT + plan dur sans cale-tête, OU BOA + demi-plan dur + plan dur concave.', 'Victime allongée (extraction à 0°, dans l’axe) : maintenir la stabilisation, techniques de relevage adaptées (pont amélioré…) ou directement au plan dur.', 'Retirer le matériel d’extraction (ACT + plan dur ; BOA + plans durs ; plan dur par brancard cuillère ou pont amélioré à 4 + 1) AVANT l’immobilisation.', 'Immobiliser dans le MID (matériel prioritaire) ; défaillance du MID : plan dur + cale-tête + sangles araignées.'],
      figs: [{ img: 'img/fiches/sr-logigramme.jpg', cap: 'Logigramme original de la procédure SR', txt: '<p>Version départementale de l’arbre décisionnel.</p>', src: 'PR - Extraction et immobilisation de la victime en SR au VSAV' }] },
    { id: 'rappels', t: 'Rappels de la procédure', ic: 'alert', src: 'PR - Extraction et immobilisation en SR',
      html: '<ul class="check"><li>L’immobilisation de la colonne ne passe jamais avant la prise en charge d’une détresse vitale.</li><li>Le chef d’agrès anticipe la méthode de relevage et d’immobilisation avant l’extraction.</li><li>La victime est toujours arrimée au brancard en plus des sangles araignées / du MID.</li><li>La position est déterminée par l’axe tête-cou-tronc.</li><li>Le plan dur est un moyen d’extraction et de brancardage ; à défaut de MID, il peut immobiliser (cales tête + sangles araignées).</li><li>Tout matériel d’extraction est obligatoirement retiré avant l’immobilisation du corps entier.</li><li>MID prioritaire, qui reste en place jusqu’au brancard de l’hôpital.</li><li>Sans brancard cuillère : pont amélioré à plusieurs secouristes.</li><li>Enfant au sol : brancard cuillère plutôt que plan dur ; plan dur réservé à l’extraction.</li></ul>' }
  ],
  key: ['Détresse vitale avant immobilisation.', 'Anticiper relevage et immobilisation avant d’extraire.', 'Assise : ACT ou BOA + plans durs ; allongée : extraction dans l’axe.', 'Tout matériel d’extraction retiré avant le MID.', 'MID prioritaire ; repli : plan dur + cale-tête + araignées.', 'Arrimage au brancard toujours.'],
  traps: ['Immobiliser dans le MID avec l’ACT ou le BOA encore en place.', 'Extraire avant d’avoir décidé de la technique de conditionnement.'],
  quiz: [
    { q: 'Victime assise : pourquoi utiliser ACT ou BOA ?', c: ['La stabilisation manuelle devient difficile pendant l’extraction', 'Pour transporter la victime jusqu’à l’hôpital', 'Pour remplacer le collier', 'Pour réchauffer la victime'], e: 'Obligation de suppléer la stabilisation par du matériel.', s: 'arbre' },
    { q: 'Matériel prioritaire pour l’immobilisation corps entier :', c: ['Le MID', 'Le plan dur', 'L’ACT', 'Le BOA'], e: 'En cas de défaillance : plan dur + cale-tête + sangles araignées.', s: 'rappels' },
    { q: 'Immobilisation du rachis non recommandée selon l’arbre :', c: ['Relâcher la stabilisation et accompagner prudemment la sortie', 'ACT systématique', 'Plan dur systématique', 'Attendre le médecin'], e: 'PR SR : branche « NON ».', s: 'arbre' }
  ]
});
